files = glob.glob("/Volumes/Code/SSIP/website/*.html")

for f in files:
    with open(f, "r") as file:
        content = file.read()
    
    modified = False
    for emoji, svg in emoji_map.items():
        if emoji in content:
            content = content.replace(emoji, svg)
            modified = True
            
    if modified:
        with open(f, "w") as file:
            file.write(content)
        print(f"Replaced emojis in {os.path.basename(f)}")
